// Pega a mensagem completa
let textoOriginal = $('Gmail Trigger2').first().json.text || '';

// Limpeza básica
let textoLimpo = textoOriginal
  .replace(/\n+/g, '\n')
  .replace(/[‌‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍‍]+/g, '')
  .replace(/\s{2,}/g, ' ')
  .trim();

// Recorte até "Abraços,"
const marcador = 'Abraços,';
const index = textoLimpo.indexOf(marcador);
if (index !== -1) {
  textoLimpo = textoLimpo.substring(0, index + marcador.length);
}

// Retorno com novo campo
return [{
  json: {
    ...$json,
    mensagemLimpa: textoLimpo
  }
}];

